import {createEffect} from './effects.js';
import {prepareExtendedEffects} from './extended-effects.js';
const $=s=>document.querySelector(s),hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(v=>v.toString(16).padStart(2,'0')).join('');
const files=['effects.js','extended-effects.js','extended-effects-worklet.js','lpf-kernel.js','lpf-reference-test.js'];
async function identities(){return Object.fromEntries(await Promise.all(files.map(async f=>[f,await hash(await(await fetch(f,{cache:'no-store'})).arrayBuffer())])));}
function base64(b){let s='';for(let i=0;i<b.length;i+=16384)s+=String.fromCharCode(...b.subarray(i,i+16384));return btoa(s);}
async function render(slope){const sr=48000,ctx=new OfflineAudioContext(4,sr,sr);await prepareExtendedEffects(ctx);const b=ctx.createBuffer(2,sr,sr);for(let i=0;i<sr;i++){b.getChannelData(0)[i]=.15+.02*Math.sin(2*Math.PI*100*i/sr)+.02*Math.sin(2*Math.PI*2000*i/sr)+(i===0?.1:0);b.getChannelData(1)[i]=-.1+.03*Math.sin(2*Math.PI*333*i/sr)+.01*Math.sin(2*Math.PI*4000*i/sr)+(i===320?.05:0);}
 const source=ctx.createBufferSource();source.buffer=b;const fx=createEffect(ctx,{name:'LPF',on:true,depth:100,params:{Slope:slope,Resonance:1.77,'Min Freq':500,'Max Freq':500}}),merge=ctx.createChannelMerger(4),modern=ctx.createChannelSplitter(2);source.connect(fx.input);fx.output.connect(modern);modern.connect(merge,0,0);modern.connect(merge,1,1);
 // Independent browser-native oracle: the old cascade, outside createEffect.
 let tail=source;const nodes=[source,merge,modern],count=Math.floor(slope/12);
 for(let i=0;i<count;i++){const n=ctx.createBiquadFilter();n.type='lowpass';n.frequency.value=500;n.Q.value=1.77/count;tail.connect(n);tail=n;nodes.push(n);}
 if(slope%12===6){const k=Math.tan(Math.PI*500/sr),b=k/(1+k),n=ctx.createIIRFilter([b,b],[1,(k-1)/(k+1)]);tail.connect(n);tail=n;nodes.push(n);}
 const reference=ctx.createChannelSplitter(2);tail.connect(reference);reference.connect(merge,0,2);reference.connect(merge,1,3);merge.connect(ctx.destination);source.start();
 try{const out=await ctx.startRendering(),pcm=[],comparison=[];for(let ch=0;ch<4;ch++){const a=out.getChannelData(ch),b=new Uint8Array(a.buffer);pcm.push({channel:ch,frames:a.length,sha256:await hash(b),base64:base64(b)});}for(let ch=0;ch<2;ch++){const x=out.getChannelData(ch),y=out.getChannelData(ch+2);let energy=0,error=0,max=0,finite=true;for(let i=0;i<x.length;i++){finite&&=Number.isFinite(x[i])&&Number.isFinite(y[i]);energy+=y[i]*y[i];error+=(x[i]-y[i])**2;max=Math.max(max,Math.abs(x[i]-y[i]));}comparison.push({channel:ch,finite,maxAbsoluteError:max,relativeRMSError:Math.sqrt(error/energy)});}return{slope,pcm,comparison,passed:comparison.every(v=>v.finite&&v.maxAbsoluteError<1e-5&&v.relativeRMSError<1e-5)};}finally{fx.dispose();for(const n of [...nodes,reference])n.disconnect();}}
$('#reference-run').onclick=async()=>{const r={startedAt:new Date().toISOString(),scope:'Actual OfflineAudioContext production LPF worklet against independent native Biquad/IIR cascade, stereo DC/tones/impulses,48000Hz/500Hz cutoff/Resonance1.77, eight slopes. No live automation, native desktop, hardware, music or Serato response acceptance.',criteria:{maxAbsoluteError:1e-5,maxRelativeRMSError:1e-5},results:[],errors:[]};$('#reference-run').disabled=true;try{r.sourceBefore=await identities();for(let slope=6;slope<=48;slope+=6){$('#reference-status').textContent='Comparing '+slope+'dB';r.results.push(await render(slope));}}catch(e){r.errors.push({message:e.message,stack:e.stack});}r.sourceAfter=await identities();r.sourceStable=JSON.stringify(r.sourceBefore)===JSON.stringify(r.sourceAfter);r.completed=r.sourceStable&&!r.errors.length&&r.results.length===8&&r.results.every(v=>v.passed);r.finishedAt=new Date().toISOString();$('#reference-original').textContent=JSON.stringify(r,null,2);$('#reference-results').textContent=JSON.stringify({...r,results:r.results.map(v=>({...v,pcm:v.pcm.map(p=>({...p,base64:'Retained in original'}))}))},null,2);const link=$('#reference-download');link.href=URL.createObjectURL(new Blob([JSON.stringify(r,null,2)],{type:'application/json'}));link.download='lpf-reference-original.json';link.hidden=false;$('#reference-status').textContent=r.completed?'Eight LPF native-node comparisons passed':'LPF comparison failure';};
